// ─── File: JwtAuthDemo.java ───
// Runnable demo: login mints JWT; filter validates it; protected call succeeds / fails.
package com.bank.jwtauth;

import java.util.*;
import java.util.logging.*;

public class JwtAuthDemo {

    private static final Logger log = Logger.getLogger("JwtAuth");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        JwtUtil jwtUtil = new JwtUtil("nbin-hmac-secret-from-vault", 900_000);
        SecurityConfig config = new SecurityConfig();
        JwtAuthFilter filter = new JwtAuthFilter(jwtUtil, config);
        LoginController login = new LoginController(jwtUtil);
        AccountController accounts = new AccountController();

        // 1) Rajesh logs in → receives a signed JWT.
        String token = login.login("rajesh", "correct-password");
        log.info(() -> "login issued token (truncated): " + token.substring(0, 12) + "...");

        // 2) Protected call WITH valid token → filter authenticates → allowed.
        SecurityContext ctx = filter.doFilter("/api/accounts/SAV2001", "Bearer " + token);
        if (ctx.authenticated) accounts.getAccount(ctx, "SAV2001");

        // 3) Protected call WITHOUT token → filter sets no auth → rejected (401).
        SecurityContext noAuth = filter.doFilter("/api/accounts/SAV2001", null);
        if (!noAuth.authenticated) log.severe("401 Unauthorized: missing/invalid token");

        // 4) Public endpoint (login) needs no token.
        boolean publicOk = config.isPublic("/api/auth/login");
        log.info(() -> "/api/auth/login is public? " + publicOk);
    }
}

// ─── util/JwtUtil.java (mint + verify tokens; single source of token logic) ───
class JwtUtil {
    private final String secret; private final long expiryMs;
    JwtUtil(String secret, long expiryMs) { this.secret = secret; this.expiryMs = expiryMs; }

    // generateToken: subject + roles + expiry, signed with the secret.
    String generateToken(String username, Set<String> roles) {
        long exp = System.currentTimeMillis() + expiryMs;
        String payload = username + "|" + String.join(",", roles) + "|" + exp;
        return payload + "." + sign(payload);   // real impl: Jwts.builder()...signWith(key)
    }
    private String sign(String payload) { return Integer.toHexString((payload + secret).hashCode()); }

    boolean isTokenValid(String token) {
        int dot = token.lastIndexOf('.');
        if (dot < 0) return false;
        String payload = token.substring(0, dot), sig = token.substring(dot + 1);
        if (!sign(payload).equals(sig)) return false;            // signature check
        long exp = Long.parseLong(payload.split("\\|")[2]);
        return System.currentTimeMillis() < exp;                 // expiry check
    }
    String extractUsername(String token) { return token.split("\\|")[0]; }
    Set<String> extractRoles(String token) {
        return new HashSet<>(Arrays.asList(token.split("\\|")[1].split(",")));
    }
}

// ─── filter/JwtAuthFilter.java (OncePerRequestFilter in real Spring) ───
class JwtAuthFilter {
    private static final Logger log = Logger.getLogger("JwtAuth");
    private final JwtUtil jwtUtil; private final SecurityConfig config;
    JwtAuthFilter(JwtUtil jwtUtil, SecurityConfig config) { this.jwtUtil = jwtUtil; this.config = config; }

    SecurityContext doFilter(String path, String authHeader) {
        if (config.isPublic(path)) return SecurityContext.authenticated("anonymous", Set.of());
        if (authHeader == null || !authHeader.startsWith("Bearer "))
            return SecurityContext.unauthenticated();
        String token = authHeader.substring(7);
        if (!jwtUtil.isTokenValid(token)) return SecurityContext.unauthenticated();
        String user = jwtUtil.extractUsername(token);
        Set<String> roles = jwtUtil.extractRoles(token);
        log.fine(() -> "authenticated " + user + " with roles " + roles);
        return SecurityContext.authenticated(user, roles);       // set SecurityContextHolder
    }
}

// ─── SecurityContext (stand-in for Spring's SecurityContextHolder) ───
class SecurityContext {
    final boolean authenticated; final String username; final Set<String> roles;
    private SecurityContext(boolean a, String u, Set<String> r) { authenticated=a; username=u; roles=r; }
    static SecurityContext authenticated(String u, Set<String> r) { return new SecurityContext(true, u, r); }
    static SecurityContext unauthenticated() { return new SecurityContext(false, null, Set.of()); }
}

// ─── config/SecurityConfig.java (public vs protected routes; filter wiring) ───
class SecurityConfig {
    private final Set<String> publicPaths = Set.of("/api/auth/login", "/health");
    boolean isPublic(String path) { return publicPaths.contains(path); }
    // Real Spring: SecurityFilterChain — sessionCreationPolicy(STATELESS),
    // permitAll() on publicPaths, anyRequest().authenticated(),
    // addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class), csrf disabled.
}

// ─── controller/LoginController.java (verify credentials → mint token) ───
class LoginController {
    private final JwtUtil jwtUtil;
    LoginController(JwtUtil jwtUtil) { this.jwtUtil = jwtUtil; }
    String login(String username, String password) {
        // Real code: authenticationManager.authenticate(...) against BCrypt-hashed password.
        if (!"correct-password".equals(password)) throw new SecurityException("bad credentials");
        return jwtUtil.generateToken(username, Set.of("CUSTOMER"));
    }
}

// ─── controller/AccountController.java (protected resource) ───
class AccountController {
    private static final Logger log = Logger.getLogger("JwtAuth");
    void getAccount(SecurityContext ctx, String accountId) {
        log.info(() -> ctx.username + " (roles " + ctx.roles + ") viewed account " + accountId);
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
